// Normaliza el correo entrante a un contrato estable.
// Tolera la salida simplificada y la completa del Gmail Trigger.
const salida = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;

  let fromEmail = '';
  let fromName = '';
  if (j.from && j.from.value && j.from.value[0]) {
    fromEmail = String(j.from.value[0].address || '');
    fromName = String(j.from.value[0].name || '');
  } else {
    const raw = String(j.From || j.from || '');
    const m = raw.match(/<([^>]+)>/);
    fromEmail = m ? m[1] : raw;
    fromName = m ? raw.replace(/<[^>]+>/, '').replace(/"/g, '') : '';
  }
  fromEmail = fromEmail.trim().toLowerCase();
  fromName = fromName.trim() || fromEmail.split('@')[0] || 'Keyuser';

  const subject = String(j.subject || j.Subject || '(sin asunto)').trim().slice(0, 200);

  // Cuerpo: se corta el historial citado para no reprocesar respuestas anteriores.
  let body = String(j.text || j.textPlain || j.snippet || '');
  body = body.split(/\r?\n\s*(?:El .{0,160}escribi[oó]:|On .{0,160}wrote:|-{3,}\s*Original Message\s*-{3,})/i)[0];
  body = body
    .split(/\r?\n/)
    .filter(l => !l.trim().startsWith('>'))
    .join('\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, 2000);

  salida.push({
    json: {
      session_id: String(j.threadId || j.id || 'sesion-sin-id'),
      thread_id: String(j.threadId || ''),
      message_id: String(j.id || ''),
      from_email: fromEmail,
      from_name: fromName.slice(0, 100),
      subject: subject,
      mensaje_actual: body || subject,
      fecha_ejecucion: new Date().toISOString()
    },
    pairedItem: { item: i }
  });
}

return salida;

