// Parseo defensivo del JSON del resumidor + saneamiento anti-ruido.
const raw = String($input.first().json.output || '');

let limpio = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
const ini = limpio.indexOf('{');
const fin = limpio.lastIndexOf('}');
if (ini !== -1 && fin !== -1 && fin > ini) {
  limpio = limpio.slice(ini, fin + 1);
}

let obj = null;
try {
  obj = JSON.parse(limpio);
} catch (e) {
  obj = null;
}

if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
  obj = {
    asunto_principal: 'Resumen no parseable en esta ejecucion',
    puntos_clave: [],
    accion_requerida: 'Revisar la salida del modulo de summarization'
  };
}

const corta = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n);

const asunto = corta(obj.asunto_principal, 200);
const puntos = (Array.isArray(obj.puntos_clave) ? obj.puntos_clave : [])
  .map(p => corta(p, 180))
  .filter(p => p.length > 0)
  .slice(0, 5);
const accion = corta(obj.accion_requerida, 250) || 'Ninguna accion pendiente';

const resumenTexto = [asunto, ...puntos.map(p => '- ' + p)].join('\n').slice(0, 900);
const datosClave = JSON.stringify({ puntos_clave: puntos, accion_requerida: accion }).slice(0, 900);

const ctx = $('Contador de Intercambios').first().json;

return [{
  json: {
    session_id: ctx.session_id,
    user_name: ctx.user_name,
    intercambios_nuevos: ctx.intercambios_nuevos,
    categoria: ctx.categoria,
    asunto_principal: asunto,
    puntos_clave: puntos,
    accion_requerida: accion,
    resumen_consolidado: resumenTexto,
    datos_clave: datosClave
  }
}];
